cpp.longest-unique-substring:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string s = d["s"];
    map<char, int> last;
    int left = 0, best = 0;
    for (int right = 0; right < s.size(); right++) {
        if (last.count(s[right]))
            left = max(left, last[s[right]] + 1);
        last[s[right]] = right;
        best = max(best, right - left + 1);
        TRACE({{"s", s}, {"left", left}, {"right", right}, {"best", best}});
    }
    return best;
}

cpp.character-replacement:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string s = d["s"];
    int k = d["k"], left = 0, most = 0, best = 0;
    map<char, int> counts;
    for (int right = 0; right < s.size(); right++) {
        most = max(most, ++counts[s[right]]);
        while (right - left + 1 - most > k)
            --counts[s[left++]];
        best = max(best, right - left + 1);
        TRACE({{"s", s}, {"left", left}, {"right", right}, {"best", best}});
    }
    return best;
}

cpp.minimum-window:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string s = d["s"], t = d["t"];
    if (t.empty())
        return "";
    map<char, int> need;
    for (char c : t)
        need[c]++;
    int missing = t.size(), left = 0, start = 0, best = INT_MAX;
    for (int right = 0; right < s.size(); right++) {
        if (need[s[right]]-- > 0)
            missing--;
        while (!missing) {
            if (right - left + 1 < best) {
                best = right - left + 1;
                start = left;
            }
            if (++need[s[left++]] > 0)
                missing++;
        }
        TRACE({{"s", s},
               {"left", left},
               {"right", right},
               {"missing", missing},
               {"best", best}});
    }
    return best == INT_MAX ? "" : s.substr(start, best);
}

cpp.three-sum:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<int> nums = d["nums"];
    sort(nums.begin(), nums.end());
    json result = json::array();
    for (int i = 0; i < int(nums.size()) - 2; i++) {
        if (i && nums[i] == nums[i - 1])
            continue;
        int left = i + 1, right = nums.size() - 1;
        while (left < right) {
            long long total = 0LL + nums[i] + nums[left] + nums[right];
            TRACE({{"nums", nums},
                   {"i", i},
                   {"left", left},
                   {"right", right},
                   {"result", result}});
            if (total < 0)
                left++;
            else if (total > 0)
                right--;
            else {
                result.push_back({nums[i], nums[left], nums[right]});
                int a = nums[left], b = nums[right];
                while (left < right && nums[left] == a)
                    left++;
                while (left < right && nums[right] == b)
                    right--;
            }
        }
    }
    return result;
}

