cpp.trapping-rain:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<int> height = d["height"];
    int left = 0, right = int(height.size()) - 1, lmax = 0, rmax = 0, water = 0;
    while (left <= right) {
        if (lmax <= rmax) {
            lmax = max(lmax, height[left]);
            water += lmax - height[left++];
        } else {
            rmax = max(rmax, height[right]);
            water += rmax - height[right--];
        }
        TRACE({{"height", height},
               {"left", left},
               {"right", right},
               {"water", water},
               {"lmax", lmax},
               {"rmax", rmax}});
    }
    return water;
}

