// Linked structures use node indices so every pointer is inspectable.
vector<int> make_links(int n, int pos = -1) {
    vector<int> links(n);
    for (int i = 0; i < n; i++)
        links[i] = i + 1 < n ? i + 1 : pos;
    return links;
}
json walk(const vector<int> &nodes, const vector<int> &links, int head) {
    json result = json::array();
    set<int> seen;
    while (head != -1 && seen.insert(head).second) {
        result.push_back(nodes.at(head));
        head = links.at(head);
    }
    return result;
}

json solve(json d) {
    vector<int> nodes = d["values"], links = make_links(nodes.size());
    int slow = nodes.empty() ? -1 : 0, fast = slow;
    while (fast != -1 && links[fast] != -1) {
        slow = links[slow];
        fast = links[links[fast]];
        TRACE({{"nodes", nodes}, {"links", links}, {"slow", slow}, {"fast", fast}});
    }
    TRACE({{"nodes", nodes}, {"links", links}, {"slow", slow}});
    return walk(nodes, links, slow);
}

