cpp.valid-parentheses:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string s = d["s"];
    vector<string> stack;
    map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    for (int i = 0; i < s.size(); i++) {
        char c = s[i];
        if (pairs.count(c)) {
            if (stack.empty() || stack.back()[0] != pairs[c])
                return false;
            stack.pop_back();
        } else
            stack.push_back(string(1, c));
        TRACE({{"s", s}, {"stack", stack}, {"i", i}});
    }
    return stack.empty();
}

cpp.reverse-polish:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<long long> stack;
    for (string token : d["tokens"]) {
        if (token == "+" || token == "-" || token == "*" || token == "/") {
            if (stack.size() < 2)
                throw runtime_error("Missing operand");
            auto b = stack.back();
            stack.pop_back();
            auto a = stack.back();
            stack.pop_back();
            if (token == "/" && !b)
                throw runtime_error("Division by zero");
            stack.push_back(token == "+"   ? a + b
                            : token == "-" ? a - b
                            : token == "*" ? a * b
                                           : a / b);
        } else
            stack.push_back(stoll(token));
        TRACE({{"stack", stack}, {"token", token}});
    }
    return stack.at(0);
}

cpp.min-stack:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<int> stack, minima;
    json result = json::array();
    for (auto op : d["operations"]) {
        string name = op[0];
        if (name == "push") {
            int v = op[1];
            stack.push_back(v);
            minima.push_back(minima.empty() ? v : min(v, minima.back()));
            result.push_back(nullptr);
        } else {
            if (stack.empty())
                throw runtime_error("Empty stack");
            if (name == "pop") {
                stack.pop_back();
                minima.pop_back();
                result.push_back(nullptr);
            } else
                result.push_back(name == "top" ? stack.back() : minima.back());
        }
        TRACE({{"stack", stack}, {"minima", minima}, {"result", result}});
    }
    return result;
}

cpp.calculator-ii:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string s = d["s"];
    s += "+";
    vector<long long> stack;
    long long value = 0;
    char operation = '+';
    for (int i = 0; i < s.size(); i++) {
        char c = s[i];
        if (isdigit(c))
            value = value * 10 + c - '0';
        else if (c != ' ') {
            if (operation == '+')
                stack.push_back(value);
            else if (operation == '-')
                stack.push_back(-value);
            else if (operation == '*')
                stack.back() *= value;
            else {
                if (!value)
                    throw runtime_error("Division by zero");
                stack.back() /= value;
            }
            operation = c;
            value = 0;
            TRACE({{"s", s}, {"stack", stack}, {"i", i}});
        }
    }
    return accumulate(stack.begin(), stack.end(), 0LL);
}

