    vector<int> added = d["newInterval"];
    int i = 0;
    while (i < intervals.size() && intervals[i][1] < added[0])
        result.push_back(intervals[i++]);
    while (i < intervals.size() && intervals[i][0] <= added[1]) {
        added[0] = min(added[0], intervals[i][0]);
        added[1] = max(added[1], intervals[i++][1]);
        TRACE({{"intervals", intervals}, {"result", result}, {"added", added}, {"i", i}});
