// Linked structures use node indices so every pointer is inspectable.
vector<int> make_links(int n, int pos = -1) {
    vector<int> links(n);
    for (int i = 0; i < n; i++)
        links[i] = i + 1 < n ? i + 1 : pos;
    return links;
}
json walk(const vector<int> &nodes, const vector<int> &links, int head) {
    json result = json::array();
    set<int> seen;
    while (head != -1 && seen.insert(head).second) {
        result.push_back(nodes.at(head));
        head = links.at(head);
    }
    return result;
}

json solve(json d) {
    vector<int> nodes = d["values"], links = make_links(nodes.size());
    if (nodes.empty())
        return json::array();
    int slow = 0, fast = 0;
    while (links[fast] != -1 && links[links[fast]] != -1) {
        slow = links[slow];
        fast = links[links[fast]];
    }
    int current = links[slow], previous = -1;
    links[slow] = -1;
    while (current != -1) {
        int following = links[current];
        links[current] = previous;
        previous = current;
        current = following;
        TRACE({{"nodes", nodes},
               {"links", links},
               {"previous", previous},
               {"current", current}});
    }
    int first = 0, second = previous;
    while (second != -1) {
        int a = links[first], b = links[second];
        links[first] = second;
        links[second] = a;
        TRACE({{"nodes", nodes}, {"links", links}, {"current", first}});
        first = a;
        second = b;
    }
    return walk(nodes, links, 0);
}

