cpp.reverse-k-group:
#include "trace.hpp"
#include <cmath>
#include <tuple>
// Linked structures use node indices so every pointer is inspectable.
vector<int> make_links(int n, int pos = -1) {
    vector<int> links(n);
    for (int i = 0; i < n; i++)
        links[i] = i + 1 < n ? i + 1 : pos;
    return links;
}
json walk(const vector<int> &nodes, const vector<int> &links, int head) {
    json result = json::array();
    set<int> seen;
    while (head != -1 && seen.insert(head).second) {
        result.push_back(nodes.at(head));
        head = links.at(head);
    }
    return result;
}

json solve(json d) {
    vector<int> nodes = d["values"], links = make_links(nodes.size());
    int k = d["k"];
    if (k < 1)
        throw runtime_error("k must be positive");
    int head = nodes.empty() ? -1 : 0, tail = -1, current = head;
    while (current != -1) {
        int end = current;
        for (int i = 1; i < k && end != -1; i++)
            end = links[end];
        if (end == -1)
            break;
        int following = links[end], previous = following, start = current;
        while (current != following) {
            int next = links[current];
            links[current] = previous;
            previous = current;
            current = next;
            TRACE({{"nodes", nodes},
                   {"links", links},
                   {"current", current},
                   {"previous", previous}});
        }
        if (tail == -1)
            head = end;
        else
            links[tail] = end;
        tail = start;
        TRACE({{"nodes", nodes}, {"links", links}, {"head", head}, {"tail", tail}});
    }
    return walk(nodes, links, head);
}

cpp.search-matrix:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<vector<int>> matrix = d["matrix"];
    if (matrix.empty() || matrix[0].empty())
        return false;
    int cols = matrix[0].size(), left = 0, right = matrix.size() * cols - 1,
        target = d["target"];
    while (left <= right) {
        int mid = (left + right) / 2, row = mid / cols, col = mid % cols;
        TRACE({{"matrix", matrix},
               {"row", row},
               {"col", col},
               {"left", left},
               {"right", right}});
        if (matrix[row][col] == target)
            return true;
        if (matrix[row][col] < target)
            left = mid + 1;
        else
            right = mid - 1;
    }
    return false;
}

