#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<int> nums = d["piles"];
    int hours = d["h"], left = 1, right = *max_element(nums.begin(), nums.end());
    while (left < right) {
        int mid = left + (right - left) / 2;
        long long needed = 0;
        for (int v : nums)
            needed += (v + 0LL + mid - 1) / mid;
        TRACE({{"nums", nums},
               {"left", left},
               {"right", right},
               {"mid", mid},
               {"needed", needed}});
        if (needed <= hours)
            right = mid;
        else
            left = mid + 1;
    }
    return left;
}

cpp.median-sorted-arrays:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<int> a = d["nums1"], b = d["nums2"];
    if (a.size() > b.size())
        swap(a, b);
    if (b.empty())
        throw runtime_error("Both arrays empty");
    int left = 0, right = a.size(), half = (a.size() + b.size() + 1) / 2;
    while (left <= right) {
        int i = (left + right) / 2, j = half - i;
        double al = i ? a[i - 1] : -INFINITY, ar = i < a.size() ? a[i] : INFINITY,
               bl = j ? b[j - 1] : -INFINITY, br = j < b.size() ? b[j] : INFINITY;
        TRACE({{"a", a}, {"b", b}, {"i", i}, {"j", j}});
        if (al <= br && bl <= ar)
            return (a.size() + b.size()) % 2 ? max(al, bl)
                                             : (max(al, bl) + min(ar, br)) / 2;
        if (al > br)
            right = i - 1;
        else
            left = i + 1;
    }
    throw runtime_error("Inputs must be sorted");
}

