#include "trace.hpp"
#include <cmath>
#include <tuple>
tuple<vector<int>, vector<int>, vector<int>> make_tree(json values) {
    vector<int> nodes, left, right;
    if (values.empty() || values[0].is_null())
        return {nodes, left, right};
    nodes.push_back(values[0]);
    left.push_back(-1);
    right.push_back(-1);
    deque<int> queue = {0};
    int index = 1;
    while (!queue.empty() && index < values.size()) {
        int parent = queue.front();
        queue.pop_front();
        for (int side = 0; side < 2 && index < values.size(); side++, index++)
            if (!values[index].is_null()) {
                (side ? right : left)[parent] = nodes.size();
                queue.push_back(nodes.size());
                nodes.push_back(values[index]);
                left.push_back(-1);
                right.push_back(-1);
            }
    }
    return {nodes, left, right};
}

json solve(json d) {
    auto [nodes, left_child, right_child] = make_tree(d["tree"]);
    deque<int> queue;
    if (!nodes.empty())
        queue.push_back(0);
    json result = json::array();
    while (!queue.empty()) {
        vector<int> level;
        int count = queue.size();
        while (count--) {
            int current = queue.front();
            queue.pop_front();
            level.push_back(nodes[current]);
            for (int child : {left_child[current], right_child[current]})
                if (child != -1)
                    queue.push_back(child);
            TRACE({{"nodes", nodes},
                   {"left_child", left_child},
                   {"right_child", right_child},
                   {"queue", queue},
                   {"current", current}});
        }
        result.push_back(level);
    }
    return result;
}

