#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    string begin = d["beginWord"], end = d["endWord"];
    set<string> words;
    for (string w : d["wordList"])
        words.insert(w);
    if (!words.count(end))
        return 0;
    deque<pair<string, int>> queue = {{begin, 1}};
    set<string> visited = {begin};
    json edges = json::array();
    while (!queue.empty()) {
        auto [current, distance] = queue.front();
        queue.pop_front();
        TRACE({{"edges", edges},
               {"current", current},
               {"queue", queue},
               {"visited", visited}});
        if (current == end)
            return distance;
        for (string word : words) {
            int diff = 0;
            for (int i = 0; i < current.size() && i < word.size(); i++)
                diff += current[i] != word[i];
            if (word.size() == current.size() && diff == 1 && !visited.count(word)) {
                visited.insert(word);
                edges.push_back({current, word});
                queue.push_back({word, distance + 1});
            }
        }
    }
    return 0;
}

