#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    json trie = json::object(), result = json::array();
    for (auto op : d["operations"]) {
        string name = op[0], word = op[1];
        json *node = &trie;
        bool found = true;
        for (char c : word) {
            string key(1, c);
            if (name == "insert" && !node->contains(key))
                (*node)[key] = json::object();
            if (!node->contains(key)) {
                found = false;
                break;
            }
            node = &(*node)[key];
        }
        if (name == "insert") {
            (*node)["$"] = true;
            result.push_back(nullptr);
        } else
            result.push_back(found && (name == "startsWith" || node->contains("$")));
        TRACE({{"trie", trie}, {"result", result}, {"word", word}});
    }
    return result;
}

cpp.word-dictionary:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    json trie = json::object(), result = json::array();
    function<bool(const json &, const string &, int)> search =
        [&](const json &node, const string &word, int i) {
            if (i == word.size())
                return node.contains("$");
            if (word[i] == '.') {
                for (auto it = node.begin(); it != node.end(); ++it)
                    if (it.key() != "$" && search(it.value(), word, i + 1))
                        return true;
                return false;
            }
            string key(1, word[i]);
            return node.contains(key) && search(node[key], word, i + 1);
        };
    for (auto op : d["operations"]) {
        string word = op[1];
        if (op[0] == "addWord") {
            json *node = &trie;
            for (char c : word) {
                string key(1, c);
                if (!node->contains(key))
                    (*node)[key] = json::object();
                node = &(*node)[key];
            }
            (*node)["$"] = true;
            result.push_back(nullptr);
        } else
            result.push_back(search(trie, word, 0));
        TRACE({{"trie", trie}, {"word", word}, {"result", result}});
    }
    return result;
}

