#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    json trie = json::object();
    for (string root : d["dictionary"]) {
        json *node = &trie;
        for (char c : root) {
            string key(1, c);
            if (!node->contains(key))
                (*node)[key] = json::object();
            node = &(*node)[key];
        }
        (*node)["$"] = true;
    }
    istringstream stream(d["sentence"].get<string>());
    string word, result;
    while (stream >> word) {
        json *node = &trie;
        string prefix;
        for (char c : word) {
            string key(1, c);
            if (node->contains("$") || !node->contains(key))
                break;
            prefix += c;
            node = &(*node)[key];
        }
        if (!result.empty())
            result += " ";
        result += node->contains("$") ? prefix : word;
        TRACE({{"trie", trie}, {"word", word}, {"result", result}});
    }
    return result;
}

cpp.word-search-ii:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<vector<string>> grid = d["board"];
    json trie = json::object();
    for (string word : d["words"]) {
        json *node = &trie;
        for (char c : word) {
            string key(1, c);
            if (!node->contains(key))
                (*node)[key] = json::object();
            node = &(*node)[key];
        }
        (*node)["$"] = word;
    }
    set<string> found;
    int rows = grid.size(), cols = rows ? grid[0].size() : 0;
    function<void(int, int, json &)> visit = [&](int row, int col, json &node) {
        if (row < 0 || col < 0 || row >= rows || col >= cols)
            return;
        string ch = grid[row][col];
        if (!node.contains(ch))
            return;
        json &next = node[ch];
        if (next.contains("$"))
            found.insert(next["$"]);
        grid[row][col] = "#";
        TRACE({{"grid", grid}, {"row", row}, {"col", col}, {"found", found}});
        visit(row + 1, col, next);
        visit(row - 1, col, next);
        visit(row, col + 1, next);
        visit(row, col - 1, next);
        grid[row][col] = ch;
    };
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            visit(r, c, trie);
    return found;
}

