        visit(row + 1, col);
        visit(row - 1, col);
        visit(row, col + 1);
        visit(row, col - 1);
    };
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (grid[r][c] == 1) {
                islands++;
                visit(r, c);
            }
    return islands;
}

