#include <tuple>

json solve(json d) {
    vector<vector<int>> grid = d["grid"];
    int rows = grid.size(), cols = rows ? grid[0].size() : 0, best = 0;
    function<int(int, int)> visit = [&](int row, int col) {
        if (row < 0 || col < 0 || row >= rows || col >= cols || grid[row][col] != 1)
            return 0;
        grid[row][col] = 0;
        TRACE({{"grid", grid}, {"row", row}, {"col", col}, {"best", best}});
        return 1 + visit(row + 1, col) + visit(row - 1, col) + visit(row, col + 1) +
               visit(row, col - 1);
    };
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            best = max(best, visit(r, c));
    return best;
}

