#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<vector<int>> grid = d["grid"];
    int rows = grid.size(), cols = rows ? grid[0].size() : 0, fresh = 0, time = 0;
    deque<pair<int, int>> queue;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 2)
                queue.push_back({r, c});
            if (grid[r][c] == 1)
                fresh++;
        }
    while (fresh && !queue.empty()) {
        int count = queue.size();
        time++;
        while (count--) {
            auto [row, col] = queue.front();
            queue.pop_front();
            for (auto [dr, dc] :
                 vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                int r = row + dr, c = col + dc;
                if (r >= 0 && c >= 0 && r < rows && c < cols && grid[r][c] == 1) {
                    grid[r][c] = 2;
                    fresh--;
                    queue.push_back({r, c});
                }
            }
            TRACE({{"grid", grid},
                   {"row", row},
                   {"col", col},
                   {"queue", queue},
                   {"time", time},
                   {"fresh", fresh}});
        }
    }
    return fresh ? -1 : time;
}

