#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<vector<int>> grid = d["heights"];
    if (grid.empty() || grid[0].empty())
        return json::array();
    int rows = grid.size(), cols = grid[0].size();
    set<pair<int, int>> pacific, atlantic;
    function<void(int, int, set<pair<int, int>> &)> visit = [&](int row, int col,
                                                                set<pair<int, int>>
                                                                    &visited) {
        if (!visited.insert({row, col}).second)
            return;
        TRACE({{"grid", grid},
               {"row", row},
               {"col", col},
               {"pacific", pacific},
               {"atlantic", atlantic},
               {"visited", visited}});
        for (auto [dr, dc] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int r = row + dr, c = col + dc;
            if (r >= 0 && c >= 0 && r < rows && c < cols && grid[r][c] >= grid[row][col])
                visit(r, c, visited);
        }
    };
    for (int r = 0; r < rows; r++) {
        visit(r, 0, pacific);
        visit(r, cols - 1, atlantic);
    }
    for (int c = 0; c < cols; c++) {
        visit(0, c, pacific);
        visit(rows - 1, c, atlantic);
    }
    json result = json::array();
    for (auto cell : pacific)
        if (atlantic.count(cell))
            result.push_back({cell.first, cell.second});
    return result;
}

