cpp.build-matrix:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    int k = d["k"];
    auto order = [&](json edges) {
        vector<vector<int>> graph(k + 1);
        vector<int> indegree(k + 1), result;
        for (auto edge : edges) {
            int a = edge[0], b = edge[1];
            graph[a].push_back(b);
            indegree[b]++;
        }
        deque<int> queue;
        for (int i = 1; i <= k; i++)
            if (!indegree[i])
                queue.push_back(i);
        while (!queue.empty()) {
            int current = queue.front();
            queue.pop_front();
            result.push_back(current);
            for (int neighbor : graph[current])
                if (--indegree[neighbor] == 0)
                    queue.push_back(neighbor);
            TRACE({{"graph", graph}, {"current", current}, {"order", result}});
        }
        if (result.size() != k)
            result.clear();
        return result;
    };
    auto rows = order(d["rowConditions"]), cols = order(d["colConditions"]);
    if (rows.empty() || cols.empty())
        return json::array();
    vector<int> position(k + 1);
    for (int i = 0; i < k; i++)
        position[cols[i]] = i;
    vector<vector<int>> grid(k, vector<int>(k));
    for (int row = 0; row < k; row++) {
        int col = position[rows[row]];
        grid[row][col] = rows[row];
        TRACE(
            {{"grid", grid}, {"row", row}, {"col", col}, {"rows", rows}, {"cols", cols}});
    }
    return grid;
}

