#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    vector<string> words = d["words"];
    map<string, set<string>> graph;
    map<string, int> indegree;
    for (auto word : words)
        for (char c : word) {
            graph[string(1, c)];
            indegree[string(1, c)] = 0;
        }
    for (int i = 1; i < words.size(); i++) {
        auto a = words[i - 1], b = words[i];
        if (a.size() > b.size() && a.substr(0, b.size()) == b)
            return "";
        for (int j = 0; j < min(a.size(), b.size()); j++)
            if (a[j] != b[j]) {
                string x(1, a[j]), y(1, b[j]);
                if (graph[x].insert(y).second)
                    indegree[y]++;
                break;
            }
    }
    deque<string> queue;
    for (auto [c, n] : indegree)
        if (!n)
            queue.push_back(c);
    string result;
    while (!queue.empty()) {
        string current = queue.front();
        queue.pop_front();
        result += current;
        for (auto neighbor : graph[current])
            if (--indegree[neighbor] == 0)
                queue.push_back(neighbor);
        TRACE({{"graph", graph},
               {"current", current},
               {"result", result},
               {"queue", queue}});
    }
    return result.size() == indegree.size() ? result : "";
}

