cpp.network-delay:
#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    int n = d["n"], start = d["k"];
    vector<vector<pair<int, int>>> graph(n + 1);
    for (auto e : d["times"])
        graph[e[0]].push_back({e[1], e[2]});
    vector<int> distance(n + 1, INT_MAX);
    distance[start] = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;
    heap.push({0, start});
    while (!heap.empty()) {
        auto [cost, current] = heap.top();
        heap.pop();
        if (cost != distance[current])
            continue;
        for (auto [neighbor, weight] : graph[current])
            if (cost + weight < distance[neighbor]) {
                distance[neighbor] = cost + weight;
                heap.push({distance[neighbor], neighbor});
            }
        TRACE({{"graph", graph},
               {"distance", distance},
               {"current", current},
               {"cost", cost}});
    }
    int best = *max_element(distance.begin() + 1, distance.end());
    return best == INT_MAX ? -1 : best;
}

