#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    int n = d["n"], start = d["start"], end = d["end"];
    vector<vector<pair<int, double>>> graph(n);
    for (int i = 0; i < d["edges"].size(); i++) {
        int a = d["edges"][i][0], b = d["edges"][i][1];
        double p = d["succProb"][i];
        graph[a].push_back({b, p});
        graph[b].push_back({a, p});
    }
    vector<double> distance(n);
    distance[start] = 1;
    priority_queue<pair<double, int>> heap;
    heap.push({1, start});
    while (!heap.empty()) {
        auto [probability, current] = heap.top();
        heap.pop();
        TRACE({{"graph", graph},
               {"distance", distance},
               {"current", current},
               {"probability", probability}});
        if (current == end)
            return probability;
        if (probability < distance[current])
            continue;
        for (auto [neighbor, p] : graph[current])
            if (probability * p > distance[neighbor]) {
                distance[neighbor] = probability * p;
                heap.push({distance[neighbor], neighbor});
            }
    }
    return 0.0;
}

