    vector<int> distance(n, INT_MAX);
    distance[src] = 0;
    for (int round = 0; round <= k; round++) {
        auto next = distance;
        for (auto e : d["flights"]) {
            int a = e[0], b = e[1], w = e[2];
            if (distance[a] != INT_MAX)
                next[b] = min(next[b], distance[a] + w);
