json solve(json d) {
    vector<vector<int>> grid = d["grid"];
    int rows = grid.size(), cols = grid.at(0).size();
    vector<vector<int>> distance(rows, vector<int>(cols, INT_MAX));
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>,
                   greater<tuple<int, int, int>>>
        heap;
    distance[0][0] = grid[0][0];
    heap.push({grid[0][0], 0, 0});
    while (!heap.empty()) {
        auto [cost, row, col] = heap.top();
        heap.pop();
        TRACE({{"grid", grid},
               {"dp", distance},
               {"row", row},
               {"col", col},
               {"cost", cost}});
        if (row == rows - 1 && col == cols - 1)
            return cost;
        if (cost != distance[row][col])
            continue;
        for (auto [dr, dc] : vector<pair<int, int>>{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int r = row + dr, c = col + dc;
            if (r >= 0 && c >= 0 && r < rows && c < cols) {
                int next = max(cost, grid[r][c]);
                if (next < distance[r][c]) {
                    distance[r][c] = next;
                    heap.push({next, r, c});
                }
            }
        }
    }
