    deque<pair<int, int>> queue;
    int time = 0, n = d["n"];
    while (!heap.empty() || !queue.empty()) {
        time++;
        if (!heap.empty()) {
            pop_heap(heap.begin(), heap.end());
            int remaining = heap.back() - 1;
            heap.pop_back();
            if (remaining)
                queue.push_back({time + n, remaining});
        }
        if (!queue.empty() && queue.front().first <= time) {
            heap.push_back(queue.front().second);
            push_heap(heap.begin(), heap.end());
            queue.pop_front();
        }
        TRACE({{"heap", heap}, {"queue", queue}, {"time", time}});
    }
    return time;
}

