        lower.push_back(value);
        push_heap(lower.begin(), lower.end());
        pop_heap(lower.begin(), lower.end());
        int moved = lower.back();
        lower.pop_back();
        upper.push_back(moved);
        push_heap(upper.begin(), upper.end(), greater<int>());
        if (upper.size() > lower.size()) {
            pop_heap(upper.begin(), upper.end(), greater<int>());
            lower.push_back(upper.back());
            upper.pop_back();
            push_heap(lower.begin(), lower.end());
        }
        double median =
            lower.size() > upper.size() ? lower[0] : (0.0 + lower[0] + upper[0]) / 2;
        result.push_back(median);
