    sort(candidates.begin(), candidates.end());
    candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());
    if (!candidates.empty() && candidates[0] <= 0)
        throw runtime_error("Candidates must be positive");
    json result = json::array();
    function<void(int, int)> visit = [&](int start, int remaining) {
        TRACE({{"path", path}, {"remaining", remaining}, {"result", result}});
        if (!remaining) {
            result.push_back(path);
            return;
        }
        for (int i = start; i < candidates.size() && candidates[i] <= remaining; i++) {
            path.push_back(candidates[i]);
            visit(i, remaining - candidates[i]);
            path.pop_back();
        }
    };
    visit(0, d["target"]);
    return result;
}

