#include "trace.hpp"
#include <cmath>
#include <tuple>

json solve(json d) {
    int n = d["n"];
    vector<string> board(n, string(n, '.'));
    set<int> columns, diagonal, antidiagonal;
    json result = json::array();
    function<void(int)> visit = [&](int row) {
        if (row == n) {
            result.push_back(board);
            return;
        }
        for (int col = 0; col < n; col++) {
            if (columns.count(col) || diagonal.count(row - col) ||
                antidiagonal.count(row + col)) {
                TRACE({{"board", board},
                       {"row", row},
                       {"col", col},
                       {"result", result},
                       {"phase", "reject"}});
                continue;
            }
            board[row][col] = 'Q';
            columns.insert(col);
            diagonal.insert(row - col);
            antidiagonal.insert(row + col);
            TRACE({{"board", board},
                   {"row", row},
                   {"col", col},
                   {"result", result},
                   {"phase", "place"}});
            visit(row + 1);
            board[row][col] = '.';
            columns.erase(col);
            diagonal.erase(row - col);
            antidiagonal.erase(row + col);
            TRACE({{"board", board},
                   {"row", row},
                   {"col", col},
                   {"result", result},
                   {"phase", "undo"}});
        }
    };
    visit(0);
    return result;
}

