        throw runtime_error("k must be 1..nums.size()");
    double total = accumulate(nums.begin(), nums.begin() + k, 0.0);
    double best = total;
    for (int right = k; right < nums.size(); ++right) {
        int left = right - k + 1;
        total += nums[right] - nums[right - k];
        best = max(best, total);
        TRACE({{"nums", nums},
               {"left", left},
               {"right", right},
               {"total", total},
               {"best", best}});
    }
    return best / k;
}

