function solve(d) {
    const { s, t } = d;
    if (!t) return "";
    const need = {};
    for (const c of t) need[c] = (need[c] || 0) + 1;
    let left = 0,
        missing = t.length,
        start = 0,
        best = Infinity;
    for (let right = 0; right < s.length; right++) {
        if ((need[s[right]] || 0) > 0) missing--;
        need[s[right]] = (need[s[right]] || 0) - 1;
        while (!missing) {
            if (right - left + 1 < best) {
                best = right - left + 1;
                start = left;
            }
            if (++need[s[left++]] > 0) missing++;
        }
        trace({ s, left, right, missing, best, need });
    }
    return best === Infinity ? "" : s.slice(start, start + best);
}

