        if (i && nums[i] === nums[i - 1]) continue;
        let left = i + 1,
            right = nums.length - 1;
        while (left < right) {
            const total = nums[i] + nums[left] + nums[right];
            trace({ nums, i, left, right, total, result });
            if (total < 0) left++;
            else if (total > 0) right--;
            else {
                result.push([nums[i], nums[left], nums[right]]);
                const a = nums[left],
                    b = nums[right];
                while (left < right && nums[left] === a) left++;
