function makeLinks(n, pos = -1) {
    return Array.from({ length: n }, (_, i) => (i + 1 < n ? i + 1 : pos));
}
function walk(nodes, links, head) {
    const result = [],
        seen = new Set();
    while (head !== -1 && !seen.has(head)) {
        seen.add(head);
        result.push(nodes[head]);
        head = links[head];
    }
    return result;
}

function solve(d) {
    const nodes = d.values,
        links = makeLinks(nodes.length);
    let slow = nodes.length ? 0 : -1,
        fast = slow;
    while (fast !== -1 && links[fast] !== -1) {
        slow = links[slow];
        fast = links[links[fast]];
        trace({ nodes, links, slow, fast });
    }
    return walk(nodes, links, slow);
}

