// Index-based links make pointer changes visible.
function makeLinks(n, pos = -1) {
    return Array.from({ length: n }, (_, i) => (i + 1 < n ? i + 1 : pos));
}

function solve(d) {
    const nodes = d.values,
        links = makeLinks(nodes.length, d.pos ?? -1);
    let slow = nodes.length ? 0 : -1,
        fast = slow;
    while (fast !== -1 && links[fast] !== -1) {
        slow = links[slow];
        fast = links[links[fast]];
        trace({ nodes, links, slow, fast });
        if (slow === fast) {
            slow = 0;
            while (slow !== fast) {
                slow = links[slow];
                fast = links[fast];
                trace({ nodes, links, slow, fast });
            }
            return slow;
