function makeTree(values) {
    const nodes = [],
        left_child = [],
        right_child = [];
    if (!values.length || values[0] === null) return { nodes, left_child, right_child };
    nodes.push(values[0]);
    left_child.push(-1);
    right_child.push(-1);
    const queue = [0];
    let index = 1;
    while (queue.length && index < values.length) {
        const parent = queue.shift();
        for (const children of [left_child, right_child]) {
            if (index >= values.length) break;
            const value = values[index++];
            if (value !== null) {
                children[parent] = nodes.length;
                queue.push(nodes.length);
                nodes.push(value);
                left_child.push(-1);
                right_child.push(-1);
            }
        }
    }
    return { nodes, left_child, right_child };
}

function solve(d) {
    const { nodes, left_child, right_child } = makeTree(d.tree);
    if (!nodes.length) return 0;
    let best = -Infinity;
    function gain(current) {
        if (current === -1) return 0;
        const a = Math.max(0, gain(left_child[current])),
            b = Math.max(0, gain(right_child[current]));
        best = Math.max(best, nodes[current] + a + b);
        trace({ nodes, left_child, right_child, current, best });
        return nodes[current] + Math.max(a, b);
    }
    gain(0);
    return best;
}

