// Binary heap: before(a,b) is true when a belongs nearer the root.
class Heap {
    constructor(before = (a, b) => a < b) {
        this.values = [];
        this.before = before;
    }
    push(value) {
        const a = this.values;
        a.push(value);
        let i = a.length - 1;
        while (i) {
            const p = (i - 1) >> 1;
            if (!this.before(a[i], a[p])) break;
            [a[i], a[p]] = [a[p], a[i]];
            i = p;
        }
    }
    pop() {
        const a = this.values;
        if (!a.length) return undefined;
        const root = a[0],
            last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                for (const c of [2 * i + 1, 2 * i + 2])
                    if (c < a.length && this.before(a[c], a[best])) best = c;
                if (best === i) break;
                [a[i], a[best]] = [a[best], a[i]];
                i = best;
            }
        }
        return root;
    }
    get size() {
        return this.values.length;
    }
    get top() {
        return this.values[0];
    }
}

function solve(d) {
    const { n, k } = d,
        graph = Array.from({ length: n + 1 }, () => []),
        distance = Array(n + 1).fill(Infinity),
        heap = new Heap((a, b) => a[0] < b[0]);
    for (const [a, b, w] of d.times) graph[a].push([b, w]);
    distance[k] = 0;
    heap.push([0, k]);
    while (heap.size) {
        const [cost, current] = heap.pop();
        if (cost !== distance[current]) continue;
        for (const [neighbor, weight] of graph[current])
            if (cost + weight < distance[neighbor]) {
                distance[neighbor] = cost + weight;
                heap.push([distance[neighbor], neighbor]);
            }
        trace({ graph, distance, current, cost, heap: heap.values });
    }
    const best = Math.max(...distance.slice(1));
    return best === Infinity ? -1 : best;
}

