class Heap {
    constructor(before = (a, b) => a < b) {
        this.values = [];
        this.before = before;
    }
    push(value) {
        const a = this.values;
        a.push(value);
        let i = a.length - 1;
        while (i) {
            const p = (i - 1) >> 1;
            if (!this.before(a[i], a[p])) break;
            [a[i], a[p]] = [a[p], a[i]];
            i = p;
        }
    }
    pop() {
        const a = this.values;
        if (!a.length) return undefined;
        const root = a[0],
            last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                let best = i;
                for (const c of [2 * i + 1, 2 * i + 2])
                    if (c < a.length && this.before(a[c], a[best])) best = c;
                if (best === i) break;
                [a[i], a[best]] = [a[best], a[i]];
                i = best;
            }
        }
        return root;
    }
    get size() {
        return this.values.length;
    }
    get top() {
        return this.values[0];
    }
}

function solve(d) {
    const { grid } = d,
        rows = grid.length,
        cols = grid[0].length,
        distance = Array.from({ length: rows }, () => Array(cols).fill(Infinity)),
        heap = new Heap((a, b) => a[0] < b[0]);
    distance[0][0] = grid[0][0];
    heap.push([grid[0][0], 0, 0]);
    while (heap.size) {
        const [cost, row, col] = heap.pop();
        trace({ grid, dp: distance, row, col, cost, heap: heap.values });
        if (row === rows - 1 && col === cols - 1) return cost;
        if (cost !== distance[row][col]) continue;
        for (const [dr, dc] of [
            [1, 0],
            [-1, 0],
            [0, 1],
            [0, -1],
        ]) {
            const r = row + dr,
                c = col + dc;
            if (r >= 0 && c >= 0 && r < rows && c < cols) {
                const next = Math.max(cost, grid[r][c]);
                if (next < distance[r][c]) {
                    distance[r][c] = next;
                    heap.push([next, r, c]);
                }
            }
        }
    }
    return -1;
}

