function solve(d) {
    const counts = {};
    for (const task of d.tasks) counts[task] = (counts[task] || 0) + 1;
    const heap = new Heap((a, b) => a > b),
        queue = [];
    for (const count of Object.values(counts)) heap.push(count);
    let time = 0;
    while (heap.size || queue.length) {
        time++;
        if (heap.size) {
            const remaining = heap.pop() - 1;
            if (remaining) queue.push([time + d.n, remaining]);
        }
        if (queue.length && queue[0][0] <= time) heap.push(queue.shift()[1]);
        trace({ heap: heap.values, queue, time });
    }
    return time;
}

