function solve(d) {
    const lower = new Heap((a, b) => a > b),
        upper = new Heap(),
        result = [];
    for (const value of d.nums) {
        lower.push(value);
        upper.push(lower.pop());
        if (upper.size > lower.size) lower.push(upper.pop());
        const median = lower.size > upper.size ? lower.top : (lower.top + upper.top) / 2;
        result.push(median);
        trace({ lower: lower.values, upper: upper.values, median, result });
    }
    return result;
}

javascript.subsets:
function solve(d) {
    const { nums } = d,
        path = [],
        result = [];
    function visit(start) {
        result.push([...path]);
        trace({ nums, path, result, start });
        for (let i = start; i < nums.length; i++) {
            path.push(nums[i]);
            visit(i + 1);
            path.pop();
        }
    }
    visit(0);
    return result;
}

javascript.combination-sum:
function solve(d) {
    const candidates = [...new Set(d.candidates)].sort((a, b) => a - b),
        path = [],
        result = [];
    if (candidates.some((v) => v <= 0)) throw Error("Candidates must be positive");
    function visit(start, remaining) {
        trace({ path, remaining, result });
        if (!remaining) {
            result.push([...path]);
            return;
        }
        for (let i = start; i < candidates.length && candidates[i] <= remaining; i++) {
            path.push(candidates[i]);
            visit(i, remaining - candidates[i]);
            path.pop();
        }
    }
    visit(0, d.target);
    return result;
}

javascript.phone-letters:
function solve(d) {
    const { digits } = d,
        letters = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"],
        result = [];
    let path = "";
    function visit(i) {
        trace({ path, digits, i, result });
        if (i === digits.length) {
            result.push(path);
            return;
        }
        for (const c of letters[Number(digits[i])]) {
            path += c;
            visit(i + 1);
            path = path.slice(0, -1);
        }
    }
    if (digits) visit(0);
    return result;
}

javascript.n-queens:
function solve(d) {
    const { n } = d,
        board = Array.from({ length: n }, () => Array(n).fill(".")),
        columns = new Set(),
        diagonal = new Set(),
        antidiagonal = new Set(),
        result = [];
    function visit(row) {
        if (row === n) {
            result.push(board.map((r) => r.join("")));
            return;
        }
        for (let col = 0; col < n; col++) {
            if (
                columns.has(col) ||
                diagonal.has(row - col) ||
                antidiagonal.has(row + col)
            ) {
                trace({ board, row, col, result, phase: "reject" });
                continue;
            }
            board[row][col] = "Q";
            columns.add(col);
            diagonal.add(row - col);
            antidiagonal.add(row + col);
            trace({ board, row, col, result, phase: "place" });
            visit(row + 1);
            board[row][col] = ".";
            columns.delete(col);
            diagonal.delete(row - col);
            antidiagonal.delete(row + col);
            trace({ board, row, col, result, phase: "undo" });
        }
    }
    visit(0);
    return result;
}

javascript.climbing-stairs:
function solve(d) {
    const { n } = d,
        dp = Array(n + 1).fill(1);
    for (let i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
        trace({ dp, i });
    }
    return dp[n];
}

javascript.house-robber:
function solve(d) {
    const { nums } = d,
        dp = Array(nums.length + 2).fill(0);
    for (let i = 0; i < nums.length; i++) {
        dp[i + 2] = Math.max(dp[i + 1], dp[i] + nums[i]);
        trace({ nums, dp, i });
    }
    return dp.at(-1);
}

javascript.palindromic-substrings:
function solve(d) {
    const { s } = d,
        dp = Array.from({ length: s.length }, () => Array(s.length).fill(false));
    let count = 0;
    for (let left = s.length - 1; left >= 0; left--)
        for (let right = left; right < s.length; right++) {
            dp[left][right] =
                s[left] === s[right] && (right - left < 2 || dp[left + 1][right - 1]);
            if (dp[left][right]) count++;
            trace({ s, dp, left, right, count });
        }
    return count;
}

javascript.decode-ways:
function solve(d) {
    const { s } = d;
    if (!s) return 0;
    const dp = Array(s.length + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= s.length; i++) {
        if (s[i - 1] !== "0") dp[i] += dp[i - 1];
        const pair = Number(s.slice(i - 2, i));
        if (i >= 2 && pair >= 10 && pair <= 26) dp[i] += dp[i - 2];
        trace({ s, dp, i });
    }
    return dp.at(-1);
}

javascript.unique-paths:
function solve(d) {
    const { m, n } = d;
    if (m <= 0 || n <= 0) return 0;
    const dp = Array.from({ length: m }, () => Array(n).fill(1));
    for (let row = 1; row < m; row++)
        for (let col = 1; col < n; col++) {
            dp[row][col] = dp[row - 1][col] + dp[row][col - 1];
            trace({ dp, row, col });
        }
    return dp.at(-1).at(-1);
}

javascript.longest-common-subsequence:
function solve(d) {
    const a = d.text1,
        b = d.text2,
        dp = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
    for (let i = 1; i <= a.length; i++)
        for (let j = 1; j <= b.length; j++) {
            dp[i][j] =
                a[i - 1] === b[j - 1]
                    ? 1 + dp[i - 1][j - 1]
                    : Math.max(dp[i - 1][j], dp[i][j - 1]);
            trace({ dp, i, j, a, b });
        }
    return dp.at(-1).at(-1);
}

javascript.edit-distance:
function solve(d) {
    const a = d.word1,
        b = d.word2,
        dp = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
    for (let i = 0; i <= a.length; i++) dp[i][0] = i;
    for (let j = 0; j <= b.length; j++) dp[0][j] = j;
    for (let i = 1; i <= a.length; i++)
        for (let j = 1; j <= b.length; j++) {
            dp[i][j] =
                a[i - 1] === b[j - 1]
                    ? dp[i - 1][j - 1]
                    : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
            trace({ dp, i, j, a, b });
        }
    return dp.at(-1).at(-1);
}

javascript.burst-balloons-dp:
function solve(d) {
    const nums = [1, ...d.nums, 1],
        n = nums.length,
        dp = Array.from({ length: n }, () => Array(n).fill(0));
    for (let width = 2; width < n; width++)
        for (let left = 0; left + width < n; left++) {
            const right = left + width;
            for (let k = left + 1; k < right; k++) {
                dp[left][right] = Math.max(
                    dp[left][right],
                    dp[left][k] + nums[left] * nums[k] * nums[right] + dp[k][right],
                );
                trace({ nums, dp, left, right, k });
            }
        }
    return dp[0][n - 1];
}

javascript.coin-change:
function solve(d) {
    const { amount, coins } = d,
        dp = Array(amount + 1).fill(amount + 1);
    dp[0] = 0;
    for (let i = 1; i <= amount; i++) {
        for (const coin of coins)
            if (coin > 0 && coin <= i) dp[i] = Math.min(dp[i], 1 + dp[i - coin]);
        trace({ dp, i, coins });
    }
    return dp[amount] > amount ? -1 : dp[amount];
}

javascript.target-sum:
function solve(d) {
    let dp = new Map([[0, 1]]);
    for (const value of d.nums) {
        const next = new Map();
        for (const [total, count] of dp) {
            next.set(total + value, (next.get(total + value) || 0) + count);
            next.set(total - value, (next.get(total - value) || 0) + count);
        }
        dp = next;
        trace({ dp, value });
    }
    return dp.get(d.target) || 0;
}

javascript.stock-cooldown:
function solve(d) {
    let hold = -Infinity,
        sold = -Infinity,
        rest = 0;
    const dp = [];
    for (const price of d.prices) {
        [hold, sold, rest] = [
            Math.max(hold, rest - price),
            hold + price,
            Math.max(rest, sold),
        ];
        dp.push([hold, sold, rest]);
        trace({ dp, hold, sold, rest, price });
    }
    return Math.max(rest, sold);
}

javascript.regex-matching:
function solve(d) {
    const { s, p } = d,
        dp = Array.from({ length: s.length + 1 }, () => Array(p.length + 1).fill(false));
    dp[0][0] = true;
    for (let j = 2; j <= p.length; j++) if (p[j - 1] === "*") dp[0][j] = dp[0][j - 2];
    for (let i = 1; i <= s.length; i++)
        for (let j = 1; j <= p.length; j++) {
            if (p[j - 1] === "*" && j >= 2)
                dp[i][j] =
                    dp[i][j - 2] ||
                    ((p[j - 2] === "." || p[j - 2] === s[i - 1]) && dp[i - 1][j]);
            else if (p[j - 1] === "." || p[j - 1] === s[i - 1])
                dp[i][j] = dp[i - 1][j - 1];
            trace({ dp, s, p, i, j });
        }
    return dp.at(-1).at(-1);
}

javascript.jump-game:
function solve(d) {
    const { nums } = d;
    let farthest = 0;
    for (let i = 0; i < nums.length; i++) {
        if (i > farthest) return false;
        farthest = Math.max(farthest, i + nums[i]);
        trace({ nums, i, farthest });
    }
    return nums.length > 0;
}

javascript.jump-game-ii:
function solve(d) {
    const { nums } = d;
    if (!nums.length) return -1;
    let end = 0,
        farthest = 0,
        jumps = 0;
    for (let i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i === end) {
            if (farthest <= i) return -1;
            end = farthest;
            jumps++;
        }
        trace({ nums, i, end, farthest, jumps });
    }
    return jumps;
}

javascript.gas-station:
function solve(d) {
    const { gas, cost } = d;
    let total = 0,
        tank = 0,
        start = 0;
    for (let i = 0; i < gas.length; i++) {
        const delta = gas[i] - cost[i];
        total += delta;
        tank += delta;
        if (tank < 0) {
            tank = 0;
            start = i + 1;
        }
        trace({ gas, cost, i, tank, start });
    }
    return total >= 0 && gas.length ? start : -1;
}

javascript.candy:
function solve(d) {
    const { ratings } = d,
        candies = Array(ratings.length).fill(1);
    for (let i = 1; i < ratings.length; i++) {
        if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
        trace({ ratings, candies, i });
    }
    for (let i = ratings.length - 2; i >= 0; i--) {
        if (ratings[i] > ratings[i + 1])
            candies[i] = Math.max(candies[i], candies[i + 1] + 1);
        trace({ ratings, candies, i });
    }
    return candies.reduce((a, b) => a + b, 0);
}

