javascript.counting-bits:
function solve(d) {
    const dp = Array(d.n + 1).fill(0);
    for (let i = 1; i < dp.length; i++) {
        dp[i] = dp[i >> 1] + (i & 1);
        trace({ dp, i });
    }
    return dp;
}

javascript.reverse-bits:
function solve(d) {
    let n = d.n >>> 0,
        result = 0;
    for (let i = 0; i < 32; i++) {
        result = ((result << 1) | (n & 1)) >>> 0;
        n >>>= 1;
        trace({ n, result, i });
    }
    return result;
}

javascript.sum-two-integers:
function solve(d) {
    let a = d.a | 0,
        b = d.b | 0;
    while (b) {
        const carry = (a & b) << 1;
        a ^= b;
        b = carry;
        trace({ a, b, carry });
    }
    return a;
}

javascript.strstr:
function solve(d) {
    const { haystack, needle } = d;
    if (!needle) return 0;
    const lps = Array(needle.length).fill(0);
    let j = 0;
    for (let i = 1; i < needle.length; i++) {
        while (j && needle[i] !== needle[j]) j = lps[j - 1];
        if (needle[i] === needle[j]) j++;
        lps[i] = j;
        trace({ needle, lps, i, j });
    }
    j = 0;
    for (let i = 0; i < haystack.length; i++) {
        while (j && haystack[i] !== needle[j]) j = lps[j - 1];
        if (haystack[i] === needle[j]) j++;
        trace({ haystack, needle, lps, i, j });
        if (j === needle.length) return i - j + 1;
    }
    return -1;
}

javascript.repeated-dna:
function solve(d) {
    const { s } = d,
        codes = { A: 0, C: 1, G: 2, T: 3 },
        seen = new Set(),
        repeated = new Set(),
        result = [];
    let rolling = 0;
    for (let i = 0; i < s.length; i++) {
        rolling = ((rolling << 2) | codes[s[i]]) & ((1 << 20) - 1);
        if (i >= 9) {
            if (seen.has(rolling) && !repeated.has(rolling)) {
                result.push(s.slice(i - 9, i + 1));
                repeated.add(rolling);
            }
            seen.add(rolling);
        }
        trace({ s, i, rolling, result });
    }
    return result;
}

javascript.happy-prefix:
function solve(d) {
    const { s } = d;
    if (!s) return "";
    const lps = Array(s.length).fill(0);
    let j = 0;
    for (let i = 1; i < s.length; i++) {
        while (j && s[i] !== s[j]) j = lps[j - 1];
        if (s[i] === s[j]) j++;
        lps[i] = j;
        trace({ s, lps, i, j });
    }
    return s.slice(0, lps.at(-1));
}

javascript.shortest-palindrome:
function solve(d) {
    const { s } = d,
        sequence = [...s, null, ...[...s].reverse()],
        lps = Array(sequence.length).fill(0);
    let j = 0;
    for (let i = 1; i < sequence.length; i++) {
        while (j && sequence[i] !== sequence[j]) j = lps[j - 1];
        if (sequence[i] === sequence[j]) j++;
        lps[i] = j;
        trace({ s, sequence, lps, i, j });
    }
    return [...s.slice(lps.at(-1))].reverse().join("") + s;
}

javascript.maximum-average-subarray:
function solve(data) {
    const { nums, k } = data;
    if (k < 1 || k > nums.length) throw Error("k must be 1..nums.length");
    let total = nums.slice(0, k).reduce((a, b) => a + b, 0);
    let best = total;
    for (let right = k; right < nums.length; right++) {
        const left = right - k + 1;
        total += nums[right] - nums[right - k];
        best = Math.max(best, total);
        trace({ nums, left, right, total, best });
    }
    return best / k;
}

javascript.binary-search-standard:
function solve(data) {
    const { nums, target } = data;
    let left = 0,
        right = nums.length - 1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        trace({ nums, left, right, mid });
        if (nums[mid] === target) return mid;
        if (nums[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

javascript.two-sum-sorted:
function solve(data) {
    const { nums, target } = data;
    let left = 0,
        right = nums.length - 1;
    while (left < right) {
        const total = nums[left] + nums[right];
        trace({ nums, left, right, total });
        if (total === target) return [left + 1, right + 1];
        if (total < target) left++;
        else right--;
    }
    return [];
}
